WITH kept_keys AS (SELECT category FROM products INTERSECT SELECT category FROM products WHERE cost >= 500), verified AS (SELECT s.* FROM products s INNER JOIN kept_keys k ON s.category = k.category) SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, ROUND(AVG(price), 2) AS avg_price, SUM(CASE WHEN category = 'Electronics' THEN cost ELSE 0 END) AS electronics_cost FROM verified GROUP BY 1;
